// Input Validation & Topic Extraction for RAG
let requestData;

// Extract VSL data from webhook
const webhookData = $json;
console.log('Webhook received:', Object.keys(webhookData));

// Handle different input formats
if (webhookData && webhookData.body) {
  requestData = webhookData.body;
} else if (webhookData && webhookData.vsl_text) {
  requestData = webhookData;
} else {
  const input = $input.all();
  requestData = input[0]?.json || input[0] || {};
}

// Validate VSL text
if (!requestData || !requestData.vsl_text) {
  throw new Error('vsl_text is required in request body');
}

// Clean VSL text
const cleanVslText = requestData.vsl_text
  .trim()
  .replace(/\s+/g, ' ')
  .replace(/[\u201C\u201D]/g, '"')
  .replace(/[\u2018\u2019]/g, "'");

if (cleanVslText.length < 50) {
  throw new Error('VSL text must be at least 50 characters long');
}

// INTELLIGENT RAG query generation based on VSL content
function generateRAGQueries(vslText) {
  const text = vslText.toLowerCase();
  const queries = [];

  // Always include core Eugene concepts
  queries.push('Eugene Schwartz market consciousness levels');
  queries.push('breakthrough advertising methodology');

  // Consciousness level detection queries
  if (text.includes('descoberta') || text.includes('discovery') || text.includes('segredo') || text.includes('você não sabia')) {
    queries.push('unaware of problem consciousness level');
    queries.push('creating awareness in prospects');
    queries.push('educating unaware market');
  }

  if (text.includes('problema') || text.includes('dor') || text.includes('frustração')) {
    queries.push('problem aware consciousness level');
    queries.push('problem agitation techniques');
    queries.push('pain amplification Eugene Schwartz');
  }

  if (text.includes('solução') || text.includes('método') || text.includes('sistema')) {
    queries.push('solution aware consciousness level');
    queries.push('product differentiation techniques');
    queries.push('competitive advantage copywriting');
  }

  if (text.includes('prova') || text.includes('resultado') || text.includes('testemunho')) {
    queries.push('product aware consciousness level');
    queries.push('proof and credibility techniques');
    queries.push('testimonial effectiveness');
  }

  if (text.includes('oferta') || text.includes('comprar') || text.includes('clique')) {
    queries.push('ready to buy consciousness level');
    queries.push('urgency and scarcity techniques');
    queries.push('call to action optimization');
  }

  // Framework detection queries
  if (text.includes('antes') && text.includes('depois')) {
    queries.push('before after bridge framework');
    queries.push('transformation storytelling');
  }

  if (text.includes('atenção')) {
    queries.push('AIDA framework copywriting');
    queries.push('attention grabbing techniques');
  }

  // Health market specific queries
  if (text.includes('saúde') || text.includes('emagr') || text.includes('peso') || text.includes('gordura')) {
    queries.push('health market copy examples');
    queries.push('weight loss advertising Eugene');
    queries.push('health claims copywriting');
    queries.push('transformation results health');
  }

  // Headline and desire queries
  if (text.includes('15 segundo') || text.includes('rápido') || text.includes('fácil')) {
    queries.push('speed benefit headlines');
    queries.push('convenience promise techniques');
  }

  // Mechanism queries
  if (text.includes('processo') || text.includes('funciona') || text.includes('como')) {
    queries.push('mechanism explanation techniques');
    queries.push('how it works copywriting');
    queries.push('scientific credibility');
  }

  // Story and curiosity queries
  if (text.includes('história') || text.includes('descobriu') || text.includes('cientista')) {
    queries.push('storytelling in copywriting');
    queries.push('authority figure credibility');
    queries.push('curiosity gap techniques');
  }

  return queries.slice(0, 12); // Limit for performance
}

const ragQueries = generateRAGQueries(cleanVslText);

// Prepare processed data
const processedData = {
  vsl_text: cleanVslText,
  analysis_id: `eugene_rag_${Date.now()}`,
  timestamp: new Date().toISOString(),
  rag_queries: ragQueries,
  options: requestData.options || {
    detailed_analysis: true,
    min_problems: 5,
    min_angles: 3,
    eugene_knowledge: true
  },
  metadata: {
    word_count: cleanVslText.split(' ').length,
    char_count: cleanVslText.length,
    estimated_reading_time: Math.ceil(cleanVslText.split(' ').length / 200),
    rag_queries_generated: ragQueries.length,
    knowledge_enhanced: true
  }
};

console.log(`Eugene RAG Analysis Started - ID: ${processedData.analysis_id}`);
console.log(`RAG queries generated: ${ragQueries.length}`);
console.log(`Queries: ${ragQueries.join(', ')}`);

return processedData;

// DYNAMIC RAG - Intelligent relevance-based filtering
console.log('=== EUGENE DYNAMIC RAG PROCESSING ===');

const processedData = $('Input & RAG Query Generation').first().json;

// O N8N retorna 5 objetos separados, não um array!
const allInputs = $input.all();
console.log('Total RAG inputs received:', allInputs.length);

let ragContext = '';
let ragStats = {
  chunks_retrieved: 0,
  categories_covered: [],
  queries_successful: 0,
  total_queries: processedData?.rag_queries?.length || 0
};

try {
  // DYNAMIC RAG PROCESSING - Filter by relevance
  let allChunks = [];
  let validChunks = [];

  // Collect all chunks first
  allInputs.forEach((inputItem, index) => {
    const chunk = inputItem.json;
    console.log(`Processing chunk ${index + 1}:`, Object.keys(chunk));

    if (chunk && chunk.content && chunk.similarity_score) {
      allChunks.push({
        ...chunk,
        index: index + 1
      });
      console.log(`📥 Chunk ${index + 1} - relevance: ${(chunk.similarity_score * 100).toFixed(0)}%`);
    } else {
      console.log(`❌ Chunk ${index + 1} invalid or no similarity score`);
    }
  });

  // DYNAMIC FILTERING LOGIC
  const minScore = 0.7;  // Minimum 70% relevance
  const maxChunks = 8;   // Maximum 8 chunks
  const minChunks = 2;   // Minimum 2 chunks

  console.log(`=== DYNAMIC FILTERING ===`);
  console.log(`Total chunks received: ${allChunks.length}`);
  console.log(`Min relevance threshold: ${(minScore * 100)}%`);

  // Filter by relevance score
  const highRelevanceChunks = allChunks.filter(chunk => chunk.similarity_score >= minScore);
  console.log(`High relevance chunks (>=${(minScore * 100)}%): ${highRelevanceChunks.length}`);

  // Adaptive selection
  if (highRelevanceChunks.length >= minChunks) {
    // Use high relevance chunks
    validChunks = highRelevanceChunks.slice(0, maxChunks);
    console.log(`✅ Using ${validChunks.length} high-relevance chunks`);
  } else {
    // Fallback: use top chunks even if lower relevance
    const sortedChunks = allChunks.sort((a, b) => b.similarity_score - a.similarity_score);
    validChunks = sortedChunks.slice(0, Math.max(minChunks, Math.min(allChunks.length, 5)));
    console.log(`⚠️ Fallback: Using top ${validChunks.length} chunks (lower relevance)`);
  }

  // Track categories from selected chunks
  validChunks.forEach(chunk => {
    const category = chunk.category || 'general';
    if (!ragStats.categories_covered.includes(category)) {
      ragStats.categories_covered.push(category);
    }
  });

  console.log('Valid chunks found:', validChunks.length);

  if (validChunks.length > 0) {
    ragContext = 'EUGENE SCHWARTZ BREAKTHROUGH ADVERTISING KNOWLEDGE FROM BOOK:\n\n';

    validChunks.forEach((chunk, index) => {
      const category = chunk.category || 'general';
      const score = chunk.similarity_score ? ` (relevance: ${(chunk.similarity_score * 100).toFixed(0)}%)` : '';
      const chapter = chunk.chapter ? ` - ${chunk.chapter}` : '';

      ragContext += `[CHUNK ${index + 1} - ${category.toUpperCase()}${score}${chapter}]\n${chunk.content}\n\n---\n\n`;
    });

    ragStats.chunks_retrieved = validChunks.length;
    ragStats.queries_successful = processedData.rag_queries.length;

    console.log('✅ SUCCESS: Built context with', validChunks.length, 'chunks');
    console.log('✅ Context length:', ragContext.length, 'characters');
    console.log('✅ Categories:', ragStats.categories_covered.join(', '));
  } else {
    console.log('❌ No valid chunks found');
  }

} catch (error) {
  console.error('❌ Processing error:', error);
}

// Only fallback if NO chunks at all
if (ragStats.chunks_retrieved === 0) {
  console.log('⚠️ FALLBACK: No RAG data available');
  ragContext = 'EUGENE SCHWARTZ METHODOLOGY FALLBACK:\nUse the 5 Levels of Market Consciousness to analyze this copy.';
} else {
  console.log('✅ SUCCESS: Using real book knowledge!');
}

const enhancedData = {
  vsl_text: processedData.vsl_text,
  eugene_context: ragContext,
  analysis_id: processedData.analysis_id,
  timestamp: processedData.timestamp,
  options: processedData.options,
  rag_stats: ragStats,
  metadata: {
    ...processedData.metadata,
    rag_enhanced: ragStats.chunks_retrieved > 0,
    context_length: ragContext.length,
    knowledge_source: ragStats.chunks_retrieved > 0 ? 'breakthrough_advertising_book' : 'fallback_methodology',
    chunks_provided_to_llm: ragStats.chunks_retrieved
  }
};

console.log('=== FINAL RESULTS ===');
console.log('- Chunks provided to LLM:', ragStats.chunks_retrieved);
console.log('- Knowledge source:', enhancedData.metadata.knowledge_source);
console.log('- RAG enhanced:', enhancedData.metadata.rag_enhanced);

return enhancedData;

// Final Results Processing with Eugene Book Knowledge
const openaiResponse = $input.first().json;
const ragData = $('Eugene Knowledge Integration').first().json;

console.log('Processing Eugene analysis with book knowledge validation...');

// Parse OpenAI response
let analysis = {};
let parseSuccess = false;

try {
  const rawContent = openaiResponse.choices[0].message.content;

  // Clean JSON content
  let cleanContent = rawContent.trim();
  if (cleanContent.startsWith('```json')) {
    cleanContent = cleanContent.replace(/```json\s*/, '').replace(/\s*```$/, '');
  }
  if (cleanContent.startsWith('```')) {
    cleanContent = cleanContent.replace(/```\s*/, '').replace(/\s*```$/, '');
  }

  analysis = JSON.parse(cleanContent);
  parseSuccess = true;
  console.log('Eugene book-enhanced analysis parsed successfully');
} catch (error) {
  console.error('Error parsing Eugene analysis:', error);
  parseSuccess = false;
}

// Enhanced validation with book knowledge criteria
function validateEugeneBookAnalysis(analysis) {
  const validation = {
    valid: true,
    errors: [],
    warnings: [],
    book_knowledge_score: 0
  };

  // Check required Eugene-specific fields
  const requiredFields = [
    'analise_consciencia',
    'estrutura_copy', 
    'problemas_identificados',
    'melhorias_sugeridas',
    'novos_angulos',
    'resumo_executivo',
    'conhecimento_aplicado'
  ];

  for (const field of requiredFields) {
    if (!analysis[field]) {
      validation.errors.push(`Missing Eugene-specific field: ${field}`);
      validation.valid = false;
    }
  }

  // Check book knowledge application
  if (analysis.conhecimento_aplicado) {
    const knowledge = analysis.conhecimento_aplicado;
    if (knowledge.principios_breakthrough_usados && knowledge.principios_breakthrough_usados.length > 0) {
      validation.book_knowledge_score += 25;
    }
    if (knowledge.tecnicas_livro_aplicadas && knowledge.tecnicas_livro_aplicadas.length > 0) {
      validation.book_knowledge_score += 25;
    }
    if (knowledge.referencias_especificas && knowledge.referencias_especificas.length > 0) {
      validation.book_knowledge_score += 25;
    }
    if (knowledge.autoridade_eugene) {
      validation.book_knowledge_score += 25;
    }
  }

  // Check minimum counts
  const problems = analysis.problemas_identificados || [];
  const improvements = analysis.melhorias_sugeridas || [];
  const angles = analysis.novos_angulos || [];

  if (problems.length < 5) {
    validation.warnings.push(`Only ${problems.length} problems found, Eugene requires minimum 5`);
  }

  if (improvements.length < 5) {
    validation.warnings.push(`Only ${improvements.length} improvements found, Eugene requires minimum 5`);
  }

  if (angles.length < 3) {
    validation.warnings.push(`Only ${angles.length} angles found, Eugene requires minimum 3`);
  }

  // Check consciousness level analysis depth
  const consciousness = analysis.analise_consciencia || {};
  if (!consciousness.justificativa || consciousness.justificativa.length < 250) {
    validation.warnings.push('Eugene consciousness analysis should be at least 250 words');
  }

  return validation;
}

// Create final Eugene-enhanced response
function createEugeneResponse() {
  const timestamp = new Date().toISOString();
  const processingTime = new Date() - new Date(ragData.timestamp);
  const totalTokens = openaiResponse.usage?.total_tokens || 0;
  const costEstimate = (totalTokens / 1000) * 0.002;

  if (!parseSuccess) {
    // Fallback response
    return {
      meta: {
        analysis_id: ragData.analysis_id,
        timestamp: timestamp,
        analyst: 'Eugene Schwartz AI (Book Enhanced)',
        version: 'eugene-rag-v1.0',
        status: 'parse_error'
      },
      error: true,
      error_message: 'Failed to parse Eugene book-enhanced analysis',
      knowledge_source: ragData.metadata.knowledge_source,
      rag_stats: ragData.rag_stats
    };
  }

  // Validate analysis
  const validation = validateEugeneBookAnalysis(analysis);

  // Build comprehensive response
  const response = {
    // Meta information
    meta: {
      analysis_id: ragData.analysis_id,
      timestamp: timestamp,
      analyst: 'Eugene Schwartz AI (Book Knowledge Enhanced)',
      version: 'eugene-rag-integrated-v1.0',
      client: 'Vitascience Squad IA',
      status: validation.valid ? 'success' : 'partial_success',
      knowledge_source: ragData.metadata.knowledge_source
    },

    // Eugene analysis with book knowledge
    ...analysis,

    // Enhanced summary
    resumo_executivo: {
      ...analysis.resumo_executivo,
      nivel_consciencia: analysis.analise_consciencia?.nivel_identificado || 0,
      framework_principal: analysis.estrutura_copy?.framework_principal || '',
      total_problemas: (analysis.problemas_identificados || []).length,
      total_melhorias: (analysis.melhorias_sugeridas || []).length,
      total_angulos: (analysis.novos_angulos || []).length,
      breakthrough_grade: analysis.resumo_executivo?.breakthrough_grade || 'C'
    },

    // RAG and knowledge statistics
    eugene_knowledge: {
      source: ragData.metadata.knowledge_source,
      book_enhanced: ragData.metadata.rag_enhanced,
      chunks_used: ragData.rag_stats.chunks_retrieved,
      categories_covered: ragData.rag_stats.categories_covered,
      context_length: ragData.metadata.context_length,
      queries_executed: ragData.rag_stats.total_queries,
      book_knowledge_score: validation.book_knowledge_score,
      authenticity: ragData.rag_stats.chunks_retrieved > 0 ? 'breakthrough_advertising_verified' : 'methodology_based'
    },

    // Performance metrics
    performance: {
      tokens_used: totalTokens,
      cost_estimate: costEstimate,
      processing_time_seconds: Math.round(processingTime / 1000),
      model_used: 'gpt-4o-mini',
      parse_success: parseSuccess,
      eugene_compliant: validation.valid,
      rag_enhanced: ragData.metadata.rag_enhanced
    },

    // VSL metadata
    vsl_metadata: {
      char_count: ragData.metadata.char_count,
      word_count: ragData.metadata.word_count,
      estimated_reading_time: ragData.metadata.estimated_reading_time
    },

    // Eugene validation results
    validation: {
      eugene_book_compliant: validation.valid,
      book_knowledge_score: validation.book_knowledge_score,
      errors: validation.errors,
      warnings: validation.warnings,
      requirements_met: {
        min_problems: (analysis.problemas_identificados || []).length >= 5,
        min_improvements: (analysis.melhorias_sugeridas || []).length >= 5,
        min_angles: (analysis.novos_angulos || []).length >= 3,
        consciousness_analysis_depth: analysis.analise_consciencia?.justificativa?.length >= 250,
        book_knowledge_applied: validation.book_knowledge_score >= 75
      }
    },

    // System info
    system_info: {
      llm_provider: 'openai',
      analysis_approach: 'eugene_book_enhanced',
      rag_integration: 'breakthrough_advertising',
      knowledge_authenticity: ragData.rag_stats.chunks_retrieved > 0 ? 'book_verified' : 'methodology_based',
      vitascience_optimized: true
    }
  };

  return response;
}

const finalResponse = createEugeneResponse();

// Log comprehensive summary
console.log('=== EUGENE BOOK-ENHANCED ANALYSIS COMPLETE ===');
console.log(`Analysis ID: ${finalResponse.meta.analysis_id}`);
console.log(`Knowledge Source: ${finalResponse.meta.knowledge_source}`);
console.log(`Book Enhanced: ${finalResponse.eugene_knowledge.book_enhanced}`);
console.log(`Chunks Used: ${finalResponse.eugene_knowledge.chunks_used}`);
console.log(`Categories: ${finalResponse.eugene_knowledge.categories_covered.join(', ')}`);
console.log(`Book Knowledge Score: ${finalResponse.eugene_knowledge.book_knowledge_score}/100`);
console.log(`Authenticity: ${finalResponse.eugene_knowledge.authenticity}`);
if (finalResponse.resumo_executivo) {
  console.log(`Consciousness Level: ${finalResponse.resumo_executivo.nivel_consciencia}`);
  console.log(`Copy Score: ${finalResponse.resumo_executivo.score_copy}/10`);
  console.log(`Breakthrough Grade: ${finalResponse.resumo_executivo.breakthrough_grade}`);
  console.log(`Problems: ${finalResponse.resumo_executivo.total_problemas}`);
  console.log(`Improvements: ${finalResponse.resumo_executivo.total_melhorias}`);
  console.log(`Angles: ${finalResponse.resumo_executivo.total_angulos}`);
}
console.log('=============================================');

return finalResponse;
